#include "coh_class_named.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/sha.h>
static unsigned long long checks;static CohClassDictionary classes;static CohClassWorkspace workspace;static CohClassNamedDictionary owner,before;static CohClassNamedValue out,old;
#define CHECK(x) do{checks++;if(!(x)){fprintf(stderr,"named check%d: %s\n",__LINE__,#x);exit(1);}}while(0)
static uint32_t word(FILE*f){uint8_t b[4];CHECK(fread(b,1,4,f)==4);return(uint32_t)b[0]|(uint32_t)b[1]<<8|(uint32_t)b[2]<<16|(uint32_t)b[3]<<24;}
static CohStatus digest(void*p,CohBytes b,uint8_t h[32]){(void)p;SHA256(b.data,b.size,h);return COH_OK;}
static CohStatus prepare(size_t budget,size_t retained){memset(&owner,0xa5,sizeof(owner));before=owner;CohStatus s=coh_class_named_prepare(&classes,&owner,budget,retained);if(s!=COH_OK)CHECK(!memcmp(&owner,&before,sizeof(owner)));return s;}
static CohStatus get(unsigned which,CohBytes name,unsigned index,size_t budget,size_t retained){memset(&out,0xa5,sizeof(out));old=out;CohStatus s=coh_class_named_get(&owner,which,name,index,&out,budget,retained);if(s!=COH_OK)CHECK(!memcmp(&out,&old,sizeof(out)));return s;}
int main(int argc,char**argv){if(argc!=2)return 2;FILE*f=fopen(argv[1],"rb");CHECK(f);unsigned files=word(f),queries=0;CohCostumeImportDigest provider={digest,NULL,0,0};for(unsigned fi=0;fi<files;fi++){unsigned size=word(f),status=word(f);uint8_t*data=malloc(size);CHECK(data&&fread(data,1,size,f)==size);uint8_t hash[32];SHA256(data,size,hash);CHECK(coh_classes_read((CohBytes){data,size},100+fi,hash,&provider,&classes,&workspace,COH_CLASS_RAM_MAX,0)==COH_OK);CHECK(prepare(COH_CLASS_NAMED_RAM_MAX,0)==(CohStatus)status);unsigned n=word(f);if(status)CHECK(n==0);else{CHECK(owner.source==&classes&&owner.source_lease==100+fi&&owner.table_count==classes.modtable_count&&owner.validated&&!owner.runtime_generation&&!owner.actor_authority&&!memcmp(owner.source_sha256,hash,32));size_t exact=sizeof(classes)+sizeof(owner)+size+COH_CLASS_NAMED_STACK_RESERVE;CHECK(prepare(exact,0)==COH_OK);CHECK(prepare(exact,1)==COH_LIMIT);CHECK(prepare(COH_CLASS_NAMED_RAM_MAX,0)==COH_OK);for(unsigned qi=0;qi<n;qi++){unsigned which=word(f),len=word(f);char name[260];CHECK(len<sizeof(name)&&fread(name,1,len,f)==len);unsigned index=word(f),expected_status=word(f),value=word(f),found=word(f),table=word(f),applied=word(f);CohBytes key={(const uint8_t*)name,len};CHECK(get(which,key,index,COH_CLASS_NAMED_RAM_MAX,0)==(CohStatus)expected_status);if(!expected_status){CHECK(out.class_index==which&&out.requested_index==index&&out.value_word==value&&out.found==found&&out.table_index==table&&out.applied_index==applied&&!out.runtime_generation&&!out.actor_authority);if(qi<4){size_t budget=sizeof(owner)+sizeof(out)+len+sizeof(classes)+size+COH_CLASS_NAMED_STACK_RESERVE;CHECK(get(which,key,index,budget,0)==COH_OK);CHECK(get(which,key,index,budget,1)==COH_LIMIT);}}queries++;}CHECK(get(classes.count,(CohBytes){(const uint8_t*)"x",1},0,COH_CLASS_NAMED_RAM_MAX,0)==COH_STATE);CHECK(get(0,(CohBytes){(const uint8_t*)"x",1},UINT32_MAX,COH_CLASS_NAMED_RAM_MAX,0)==COH_UNSUPPORTED);CHECK(get(0,(CohBytes){(const uint8_t*)"\xff",1},0,COH_CLASS_NAMED_RAM_MAX,0)==COH_UNSUPPORTED);CHECK(coh_class_named_prepare(&classes,(CohClassNamedDictionary*)&classes,COH_CLASS_NAMED_RAM_MAX,0)==COH_INVALID);CHECK(coh_class_named_get(&owner,0,(CohBytes){(const uint8_t*)"x",1},0,(CohClassNamedValue*)&owner,COH_CLASS_NAMED_RAM_MAX,0)==COH_INVALID);if(classes.modtable_count){CohClassSpan span=classes.modtables[classes.modtable_count-1].record;classes.modtables[classes.modtable_count-1].record.end=UINT32_MAX;CHECK(prepare(COH_CLASS_NAMED_RAM_MAX,0)==COH_STATE);classes.modtables[classes.modtable_count-1].record=span;CHECK(prepare(COH_CLASS_NAMED_RAM_MAX,0)==COH_OK);}owner.source_sha256[0]^=1;CHECK(get(0,(CohBytes){(const uint8_t*)"x",1},0,COH_CLASS_NAMED_RAM_MAX,0)==COH_STATE);owner.source_sha256[0]^=1;CHECK(get(0,(CohBytes){NULL,0},0,COH_CLASS_NAMED_RAM_MAX,0)==COH_INVALID);owner.source_lease++;CHECK(get(0,(CohBytes){(const uint8_t*)"x",1},0,COH_CLASS_NAMED_RAM_MAX,0)==COH_STATE);}free(data);}CHECK(fgetc(f)==EOF);fclose(f);printf("{\"checks\":%llu,\"queries\":%u,\"files\":%u,\"owner_bytes\":%zu,\"value_bytes\":%zu,\"runtime_generation\":false,\"actor_authority\":false}\n",checks,queries,files,sizeof(owner),sizeof(out));return 0;}
